import { icon } from './icons.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const API_BASE=(window.FOODSAVER_API_URL||'').replace(/\/+$/,'');
const state={user:null,csrf:null,admin:false,config:null,notifications:[],foods:[],filter:'',socket:null,map:null,otp:null,phone:null,authProfile:null,adminLogin:false};
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=name=>(name||'?').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const when=value=>new Date(Number(value)).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const remaining=value=>{const hours=(value-Date.now())/3600000;return hours<=0?'Expired':hours<1?`${Math.ceil(hours*60)} min left`:`${Math.ceil(hours)} hours left`;};
const image=f=>e(f.image_url?(f.image_url.startsWith('http')||f.image_url.startsWith('data:')?f.image_url:`${API_BASE}${f.image_url}`):`/images/${f.food_type==='Bakery'?'bread':f.food_type==='Produce'?'vegetables':'meal'}.svg`);
const badge=value=>`<span class="status ${e(value)}">${e(value)}</span>`;
let toastTimer,routeVersion=0;
function toast(message,error=false){const t=document.querySelector('#toast');t.textContent=message;t.className=error?'error':'';t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',5000);}
async function api(path,options={}){const headers={...options.headers};if(!(options.body instanceof FormData))headers['Content-Type']='application/json';if(state.csrf)headers['X-CSRF-Token']=state.csrf;const res=await fetch(`${API_BASE}/api${path}`,{...options,credentials:'include',headers,body:options.body instanceof FormData?options.body:options.body?JSON.stringify(options.body):undefined});const data=await res.json();if(!res.ok)throw new Error(data.error||'Request failed.');return data;}
function go(path){if(location.hash===`#${path}`)render();else location.hash=path;}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><span class="eyebrow">YOUR COMMUNITY, CONNECTED</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
const addButton=`<a class="btn-primary-fs" href="#/add">${icon('plus')} Donate food</a>`;
function empty(title,description,action=''){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function stats(items){return `<div class="stats">${items.map(([value,title,note,ico])=>`<div class="stat"><div class="stat-icon">${icon(ico)}</div><div><strong>${e(value)}</strong><div class="stat-title">${title}</div><small>${note}</small></div></div>`).join('')}</div>`;}
function nav(path,name,ico,current){return `<a class="nav-link ${current===path?'active':''}" href="#${path}">${icon(ico)}${name}${path==='/notifications'&&state.notifications.some(n=>!n.is_read)?`<span class="badge-count">${state.notifications.filter(n=>!n.is_read).length}</span>`:''}</a>`;}
function shell(content,path){const u=state.user;return `<aside class="sidebar"><a class="brand" href="#/dashboard"><img src="/images/logo.svg" alt="">FoodSaver<span style="color:#88a261">.</span></a><div class="tagline">Good food. Greater good.</div><div class="nav-label">WORKSPACE</div>${nav('/dashboard','Overview','grid',path)}${nav('/available','Available food','leaf',path)}${nav('/map','Nearby food map','pin',path)}<div class="nav-label" style="margin-top:23px">MY ACTIVITY</div>${nav('/donations','My donations','box',path)}${nav('/requests','My requests','heart',path)}${nav('/notifications','Notifications','bell',path)}${nav('/profile','My profile','user',path)}${u.role==='admin'?nav('/admin','Admin console','shield',path):''}<div class="sidebar-footer"><div class="impact-note"><span class="sprout">🌱</span><strong>A little sharing goes a long way.</strong><p>Every meal shared is one less wasted, and one more reason to smile.</p></div><div class="user-block"><span class="avatar">${e(initials(u.full_name))}</span><div><strong>${e(u.full_name)}</strong><small>Community member</small></div><button class="logout-btn" data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><button class="menu-btn" aria-label="Open navigation" data-action="menu">${icon('menu')}</button><span class="mobile-brand">FoodSaver.</span><div class="breadcrumb-text">Workspace <span style="padding:0 13px">/</span><b>${e(path.startsWith('/admin')?'Admin console':({'/dashboard':'Overview','/available':'Available food','/map':'Nearby food','/add':'Donate food','/donations':'My donations','/requests':'My requests','/profile':'My profile','/notifications':'Notifications'}[path]||'Community'))}</b></div><div class="top-actions"><a class="location-chip" href="#/profile">${icon('pin')}${u.latitude!==null?'Location set':'Set your location'}</a><a href="#/notifications" class="bell ${state.notifications.some(n=>!n.is_read)?'has-unread':''}" aria-label="Notifications">${icon('bell')}</a><span class="avatar">${e(initials(u.full_name))}</span></div></header><div class="content">${state.config.demo?'<div class="demo-bar"><span class="health-dot"></span>Local demonstration • real database, sample food • SMS is simulated • pickup addresses are fictional</div>':''}${content}<div class="footer-note">Made for sharing. Built for community. &nbsp; ♡ &nbsp; FoodSaver</div></div></main>`;}
function foodCard(f){return `<article class="food-card"><a href="#/food/${e(f.food_id)}" class="food-photo" style="display:block"><img src="${image(f)}" alt="${e(f.food_name)}" loading="lazy"><span class="food-tag ${f.category==='Non-Veg'?'nonveg':''}">${e(f.category)}</span><span class="time-tag">${icon('clock')} ${remaining(f.expires_at)}</span></a><div class="food-body"><h3><a href="#/food/${e(f.food_id)}">${e(f.food_name)}</a></h3><div class="food-meta">${icon('box')}${e(f.quantity)} <span>·</span> ${e(f.people_count)} servings</div><div class="food-donor"><span class="avatar">${e(initials(f.donor_name||state.user?.full_name))}</span>${e(f.donor_name||state.user?.full_name)}<span>${f.distance_km!==null&&f.distance_km!==undefined?`${f.distance_km} km away`:'Nearby community'}</span></div><div class="card-bottom"><small>${icon('pin')} ${e(f.pickup_area)}</small><a class="btn-outline-fs" href="#/food/${e(f.food_id)}">View details ${icon('arrow')}</a></div></div></article>`;}
function foodGrid(foods){return foods.length?`<div class="food-grid">${foods.map(foodCard).join('')}</div>`:empty('No food found','Try changing the filters or check back for new donations.');}
async function render(){
  const version=++routeVersion,path=(location.hash.slice(1)||'/').split('?')[0];
  if(state.map){state.map.stop();state.map.remove();state.map=null;}
  try{
    if(path==='/'&&!state.user){landing();return;}
    if(['/login','/register','/admin-login','/verify'].includes(path)){authPage(path);return;}
    if(!state.user){go('/login');return;}
    const pages={'/dashboard':dashboard,'/available':available,'/map':mapPage,'/add':addPage,'/donations':donations,'/requests':requests,'/notifications':notifications,'/profile':profile};
    let result;
    if(path.startsWith('/food/'))result=await details(path.split('/')[2]);
    else if(path.startsWith('/chat/'))result=await chat(path.split('/')[2]);
    else if(path.startsWith('/admin'))result=await adminPage(path);
    else result=await (pages[path]||dashboard)();
    if(version!==routeVersion)return;
    app.innerHTML=shell(result.html,path);await result.after?.();
  }catch(error){if(version!==routeVersion)return;app.innerHTML=state.user?shell(empty('We couldn’t load this page',e(error.message),'<button class="btn-outline-fs" data-action="reload">Try again</button>'),path):empty('Unable to load',e(error.message));toast(error.message,true);}
}
function landing(){app.innerHTML=`<nav class="landing-nav"><a class="brand" href="#/"><img src="/images/logo.svg" alt="">FoodSaver.</a><div><a href="#/login" class="btn-outline-fs">Sign in</a> <a class="btn-primary-fs" href="#/register">Join the community ${icon('arrow')}</a></div></nav><main><section class="landing-main"><div class="landing-copy"><span class="eyebrow">SMALL ACTS. REAL IMPACT.</span><h1>Good food deserves<br>a <em>second chance.</em></h1><p>Have a little extra? Someone nearby could use it. Share surplus food, connect with your neighbours, and make a difference — one meal at a time.</p><div style="margin-top:27px"><a class="btn-primary-fs" href="#/register">Start sharing ${icon('arrow')}</a> <a class="btn-outline-fs" href="#/login">Find food near you</a></div>${state.config.demo?'<p class="auth-note">Local demo is ready. Try donor, receiver and admin accounts with simulated OTP verification.</p>':''}</div><img src="/images/sharing.svg" alt="An illustrated basket of fresh food shared with the community"></section><section class="landing-steps">${[['01','Share what you have','List surplus food with a photo, safe consumption time, and a pickup area.'],['02','Connect nearby','Find food close to you and send a request. Coordinate pickup in a private chat.'],['03','Make a difference','Collect safely, complete the handover, and give good food a second chance.']].map(([n,t,p])=>`<article class="panel"><span class="eyebrow">${n} / THE GOOD PART</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</section></main><div class="footer-note">FoodSaver • Good food. Greater good. &nbsp; <a href="#/admin-login">Administrator sign in</a></div>`;}
function authPage(path){
  const verify=path==='/verify',register=path==='/register',admin=path==='/admin-login'||verify&&state.adminLogin;
  if(verify&&!state.otp){go('/login');return;}
  if(!verify)state.adminLogin=admin;
  app.innerHTML=`<div class="auth-page"><section class="auth-story"><a class="brand" href="#/"><img src="/images/logo.svg" alt="">FoodSaver.</a><div><span class="eyebrow">THE COMMUNITY TABLE</span><h1>A little extra.<br>A lot of good.</h1><p>Good food brings people together. Let’s make sure it reaches the people who need it.</p><img class="illustration" src="/images/sharing.svg" alt="Basket of fresh donated food"></div><small style="color:#829273">Good food. Greater good.</small></section><section class="auth-form-wrap"><form class="auth-form" id="${verify?'verify-form':'login-form'}"><span class="eyebrow">${admin?'ADMINISTRATOR ACCESS':verify?'ONE LAST STEP':'WELCOME TO FOODSAVER'}</span><h2>${verify?'Check your code':register?'Join your community':admin?'Admin sign in':'Welcome back.'}</h2><p>${verify?`Enter the six-digit ${state.config.demo?'demo':'SMS'} code for ${e(state.phone)}.`:admin?'Verify your phone and authenticator to access the admin console.':'A small step towards less waste and more smiles.'}</p><div id="auth-error"></div>${verify?`${state.config.demo?`<div class="demo-bar">Local demo code: <b>${e(state.otp.code)}</b><br>Valid for 5 minutes. Never a real SMS.</div>`:''}<div class="form-field"><label for="code">Verification code</label><input id="code" name="code" class="otp-input" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus></div>${admin?(state.config.demo?'<div class="demo-bar">Demo admin factor: 654321</div>':'')+'<div class="form-field"><label for="totp">Authenticator code</label><input id="totp" name="totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required><small>Use the six-digit code from your authenticator.</small></div>':''}<button type="submit" class="btn-primary-fs">Verify & continue ${icon('arrow')}</button><p style="margin-top:22px;text-align:center"><button type="button" class="btn-link-fs" data-action="resend">Resend code</button> · <a href="#/login">Change number</a></p>`:`${register?'<div class="form-field"><label for="full-name">Full name</label><input id="full-name" name="full_name" required minlength="2" maxlength="100" autocomplete="name"></div><div class="form-field"><label for="email">Email <small>(optional)</small></label><input id="email" name="email" type="email" maxlength="254" autocomplete="email"></div>':''}<div class="form-field"><label for="phone">Mobile number</label><input id="phone" name="phone_number" type="tel" placeholder="+91 98765 43210" required autocomplete="tel"><small>Include your country code, such as +91.</small></div>${register?'<div class="form-field"><button type="button" class="btn-outline-fs" data-action="registration-gps">Use my location (optional)</button><input type="hidden" name="latitude"><input type="hidden" name="longitude"><small id="registration-location">You can also choose your location later in your profile.</small></div>':''}${state.config.demo?`<div class="demo-bar">Try a local sample account<div class="demo-accounts">${(admin?[['Admin','+919876543299']]:[['Aarav · receiver','+919876543210'],['Ananya · donor','+919876543211'],['Community Kitchen','+919876543212']]).map(([n,p])=>`<button type="button" data-action="demo-account" data-phone="${p}">${n}</button>`).join('')}</div>OTP is simulated locally. No SMS is sent.</div>`:'<p class="auth-note">Your number is used for verification and never shown publicly. Firebase processes your number to verify sign-in and prevent abuse.</p>'}<div id="recaptcha-container"></div><button type="submit" class="btn-primary-fs">Send verification code ${icon('arrow')}</button><p style="text-align:center;margin-top:25px">${register?'Already a member? <a href="#/login">Sign in</a>':admin?'<a href="#/login">Back to community sign in</a>':'New to FoodSaver? <a href="#/register">Create an account</a>'}</p>`}<p class="auth-note">Your precise location stays private until a food request is accepted.</p></form></section></div>`;
}
async function sendOTP(phone){
  if(state.config.demo)return api('/auth/demo/otp',{method:'POST',body:{phone_number:phone}});
  const {initializeApp}=await import('https://www.gstatic.com/firebasejs/12.4.0/firebase-app.js');
  const {getAuth,RecaptchaVerifier,signInWithPhoneNumber}=await import('https://www.gstatic.com/firebasejs/12.4.0/firebase-auth.js');
  if(!state.firebaseAuth)state.firebaseAuth=getAuth(initializeApp(state.config.firebase));
  state.recaptcha?.clear();state.recaptcha=new RecaptchaVerifier(state.firebaseAuth,'recaptcha-container',{size:'invisible'});
  const confirmation=await signInWithPhoneNumber(state.firebaseAuth,phone,state.recaptcha);return {confirmation,createdAt:Date.now()};
}
async function dashboard(){const [s,foods]=await Promise.all([api('/stats'),api('/food')]);state.foods=foods;return {html:`${heading(`Hello, ${e(state.user.full_name.split(' ')[0])} <span style="font-size:24px">☀</span>`,'A good day to share something good.',addButton)}<section class="hero"><div class="hero-text"><span class="eyebrow">LESS WASTE. MORE POSSIBILITY.</span><h2>Your extra meal.<br>Someone’s brighter day.</h2><p>Turn surplus food into a simple act of kindness.<br>Share with your community, right where you are.</p><a class="btn-primary-fs" href="#/add">${icon('plus')} Share food</a><a class="btn-outline-fs" href="#/available">Find a meal ${icon('arrow')}</a></div><img src="/images/sharing.svg" alt="Basket of bread, produce and meals"></section>${stats([[s.available,'Available donations','Ready to be shared','leaf'],[s.completed,'Meals picked up','Good food, saved','check'],[s.active,'Your active requests','Your next connection','heart'],[s.nearby,'Donations within 5 km',state.user.latitude===null?'Set your location to explore':'A little closer to you','pin']])}<section><div class="section-heading"><div><h2>Good food, close to you</h2><p>Fresh opportunities to make a difference.</p></div><a class="btn-link-fs" href="#/available">Explore all ${icon('arrow')}</a></div>${foodGrid(foods.slice(0,3))}</section><div class="bottom-grid"><section class="panel"><div class="section-heading"><div><h2>Your neighbourhood table</h2><p>Find food around your community.</p></div><a class="btn-link-fs" href="#/map">Open map ${icon('arrow')}</a></div><div id="mini-map" class="mini-map"></div></section><section class="panel"><div class="section-heading"><h2>A little care goes a long way</h2>${icon('leaf')}</div><div class="tip">${icon('box')}<div><h3>Pack it with kindness</h3><p>Use clean, sealed containers and include ingredient and allergen information.</p></div></div><div class="tip">${icon('clock')}<div><h3>Share while it’s fresh</h3><p>Keep food safely stored and arrange pickup before its safe consumption time.</p></div></div></section></div>`,after:()=>drawMap('mini-map',foods)};}
function filterForm(){return `<form id="filter-form" class="filters"><input name="q" placeholder="Search food or a meal…" aria-label="Search food"><select name="category" aria-label="Diet"><option value="">All diets</option><option>Veg</option><option>Non-Veg</option></select><select name="type" aria-label="Food category"><option value="">All food types</option>${['Cooked meals','Bakery','Produce','Packaged food','Other'].map(t=>`<option>${t}</option>`).join('')}</select><select name="radius" aria-label="Distance"><option value="">Any distance</option>${[1,3,5,10].map(n=>`<option value="${n}">Within ${n} km</option>`).join('')}</select><select name="people" aria-label="Servings"><option value="">Any servings</option><option value="5">5+ servings</option><option value="10">10+ servings</option><option value="20">20+ servings</option></select><select name="hours" aria-label="Safe consumption time"><option value="">Any expiry</option><option value="2">Within 2 hours</option><option value="6">Within 6 hours</option><option value="24">Within 24 hours</option></select><select name="sort" aria-label="Sort donations"><option value="nearby">Nearest first</option><option value="expiry">Expiry first</option></select><button class="btn-primary-fs" type="submit">${icon('search')} Find food</button><button class="btn-outline-fs" type="reset">Reset</button></form>`;}
async function available(){const foods=await api('/food');state.foods=foods;return {html:`${heading('Good food is waiting.','Explore fresh donations from people in your community.',addButton)}${filterForm()}<div class="section-heading"><h2><span id="food-count">${foods.length}</span> available donations</h2><a class="btn-link-fs" href="#/map">${icon('pin')} Switch to map</a></div><div id="food-results">${foodGrid(foods)}</div>`};}
async function mapPage(){const foods=await api('/food');return {html:`${heading('Your neighbourhood, sharing.','Markers show approximate pickup areas. Exact locations are shared after acceptance.','<button class="btn-outline-fs" data-action="gps">'+icon('pin')+' Use my location</button>')}<div class="section-heading"><p>${foods.length} available donations · tap a marker to see details</p><a href="#/available" class="btn-link-fs">Browse list ${icon('arrow')}</a></div><div id="food-map" class="map-large"></div>`,after:()=>drawMap('food-map',foods)};}
function drawMap(element,foods=[],editable=false,onSelect){if(!window.L)return;const center=state.user?.latitude!==null&&state.user?.latitude!==undefined?[state.user.latitude,state.user.longitude]:foods[0]?[foods[0].latitude,foods[0].longitude]:[12.9716,77.5946];const map=L.map(element).setView(center,13);state.map=map;L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles &copy; Esri',maxZoom:19}).addTo(map);let selected;


  const markerIcon=L.divIcon({html:'<div class="map-pin"><span>♧</span></div>',className:'',iconSize:[30,30],iconAnchor:[15,30]});
  for(const food of foods)L.marker([food.latitude,food.longitude],{icon:markerIcon}).addTo(map).bindPopup(`<b>${e(food.food_name)}</b><br>${e(food.pickup_area)} · ${food.people_count} servings<br><small>Approximate public location</small><br><a href="#/food/${e(food.food_id)}">View donation →</a>`);
  if(editable){const select=latlng=>{if(selected)map.removeLayer(selected);selected=L.marker(latlng).addTo(map);onSelect?.(latlng);};map.on('click',evt=>select(evt.latlng));if(state.user?.latitude!==null&&state.user?.latitude!==undefined)select(L.latLng(center[0],center[1]));state.selectMapLocation=select;}
  setTimeout(()=>{if(state.map===map&&document.getElementById(element))map.invalidateSize();},100);
}
const field=(label,name,type='text',extra='')=>`<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${extra}></div>`;
async function addPage(){const dt=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);return {html:`${heading('A little extra. A lot of good.','Tell your neighbours what you have to share.')}<form id="donation-form" class="panel"><div class="section-heading"><h2>Food details</h2><span class="eyebrow">01 / WHAT YOU’RE SHARING</span></div><div class="form-grid">${field('Food name','food_name','text','required minlength="2" maxlength="120" placeholder="e.g. Fresh vegetable bowls"')}<div class="form-field"><label for="category">Diet</label><select id="category" name="category"><option>Veg</option><option>Non-Veg</option></select></div><div class="form-field"><label for="food_type">Food type</label><select id="food_type" name="food_type">${['Cooked meals','Bakery','Produce','Packaged food','Other'].map(t=>`<option>${t}</option>`).join('')}</select></div>${field('Quantity','quantity','text','required maxlength="80" placeholder="e.g. 8 meal boxes or 3 kg"')}${field('People it can feed','people_count','number','required min="1" max="10000" value="1"')}<div class="form-field"><label for="food-image">Food photo <small>(optional)</small></label><input id="food-image" name="image" type="file" accept="image/png,image/jpeg,image/webp"><small>JPEG, PNG or WebP · maximum 5 MB</small><img id="image-preview" class="preview-image" alt="Selected food preview" hidden></div><div class="form-field full"><label for="description">Description & allergens</label><textarea id="description" name="description" required minlength="10" maxlength="2000" placeholder="What’s included? Mention ingredients, allergens, and storage instructions."></textarea></div>${field('Prepared at','prepared_at','datetime-local',`required value="${dt}"`)}${field('Safe consumption time','expires_at','datetime-local','required')}</div><hr style="border-color:#dae1d1;margin:27px 0"><div class="section-heading"><h2>Pickup details</h2><span class="eyebrow">02 / WHERE TO CONNECT</span></div><div class="form-grid">${field('Public pickup area','pickup_area','text','required minlength="2" maxlength="120" placeholder="e.g. Indiranagar"')}${field('Precise pickup address','pickup_address','text','required minlength="5" maxlength="500" placeholder="Street, building and pickup instructions"')}<div class="form-field full"><small>Your precise address is shared only with the accepted requester. Public maps show an approximate area.</small></div><div class="form-field full"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><label>Choose pickup location on the map</label><button type="button" class="btn-outline-fs" data-action="form-gps">${icon('pin')} Use GPS</button></div><div id="location-map" class="location-map"></div></div>${field('Latitude','latitude','number','required step="any" min="-90" max="90"')}${field('Longitude','longitude','number','required step="any" min="-180" max="180"')}<div class="form-field full"><label>Contact preference</label><p style="margin:0;color:#75876b">In-app chat — keeps your phone number private.</p></div><div class="form-field full"><label class="check-row"><input name="safe_storage" type="checkbox" required><span>I confirm this food has been safely prepared and stored, is suitable to share, and can be collected before the safe consumption time.</span></label></div></div><div class="form-actions"><a class="btn-outline-fs" href="#/dashboard">Cancel</a><button class="btn-primary-fs" type="submit">${icon('leaf')} Publish donation</button></div></form>`,after:()=>drawMap('location-map',[],true,loc=>{document.querySelector('[name=latitude]').value=loc.lat.toFixed(6);document.querySelector('[name=longitude]').value=loc.lng.toFixed(6);})};}
async function details(foodId){const f=await api(`/food/${foodId}`),own=f.donor_id===state.user.user_id,active=f.status==='Available'&&f.expires_at>Date.now();const exact=own||f.accepted;return {html:`${heading(e(f.food_name),`${e(f.pickup_area)} · Shared by ${e(f.donor_name)}`,'<a class="btn-outline-fs" href="#/available">Back to donations</a>')}<div class="details-grid"><div><img class="detail-photo" src="${image(f)}" alt="${e(f.food_name)}"><div class="panel" style="margin-top:20px"><h2 style="font-size:18px">Good to know</h2><p class="detail-description">${e(f.description)}</p><div class="tip">${icon('shield')}<div><h3>Shared with care</h3><p>The donor confirmed safe storage. Check food condition and allergens at pickup, and collect before its stated safe consumption time.</p></div></div></div></div><section class="panel"><div class="section-heading"><span class="food-tag ${f.category==='Non-Veg'?'nonveg':''}" style="position:static">${e(f.category)}</span>${badge(f.status)}</div><div class="detail-facts"><div><small>Quantity</small><strong>${e(f.quantity)}</strong></div><div><small>Serves</small><strong>${f.people_count} people</strong></div><div><small>Prepared</small><strong>${when(f.prepared_at)}</strong></div><div><small>Consume before</small><strong>${when(f.expires_at)}</strong></div><div><small>Pickup area</small><strong>${e(f.pickup_area)}</strong></div><div><small>Contact</small><strong>Private in-app chat</strong></div></div><div class="tip">${icon('pin')}<div><h3>${exact?'Your pickup location':'Your privacy, protected'}</h3><p>${exact?e(f.pickup_address):'The precise address and directions are available after the donor accepts your request.'}</p>${exact?`<a class="btn-link-fs" target="_blank" rel="noopener" href="https://www.openstreetmap.org/directions?to=${f.latitude}%2C${f.longitude}">Get directions →</a>`:''}</div></div><div style="margin-top:22px">${own?`<a href="#/requests" class="btn-primary-fs">Manage requests ${icon('arrow')}</a> ${['Available','Reserved'].includes(f.status)?`<button class="btn-danger-fs" data-action="cancel-food" data-id="${f.food_id}">Cancel donation</button>`:''}`:active?`<button class="btn-primary-fs" style="width:100%" data-action="request" data-id="${f.food_id}">${icon('heart')} Request this food</button>`:f.accepted?'<a class="btn-primary-fs" href="#/requests">Open your request & chat</a>':`<p style="color:#917a53">This donation is ${e(f.status.toLowerCase())}.</p>`}</div>${!own?`<button class="btn-link-fs" style="margin-top:18px;font-size:10px" data-action="report" data-id="${f.food_id}">${icon('flag')} Report a concern</button>`:''}</section></div>`};}
async function donations(){const foods=await api('/my/donations');return {html:`${heading('Your food, making a difference.','Track your donations from the first request to the final pickup.',addButton)}<div class="tabs">${['All','Available','Reserved','Collected','Expired','Cancelled'].map(t=>`<button class="chip ${t==='All'?'selected':''}" data-action="donation-filter" data-value="${t}">${t}</button>`).join('')}</div><div id="donation-list">${donationList(foods)}</div>`,after:()=>{state.donations=foods;}};}
function donationList(foods){return foods.length?foods.map(f=>`<article class="request-card"><img src="${image(f)}" alt="${e(f.food_name)}"><div class="request-info"><h3><a href="#/food/${f.food_id}">${e(f.food_name)}</a></h3><p>${e(f.quantity)} · ${f.people_count} servings · ${e(f.pickup_area)}</p><p>${remaining(f.expires_at)} · ${badge(f.status)}</p></div><div class="request-actions"><a class="btn-outline-fs" href="#/requests">View requests</a>${['Available','Reserved'].includes(f.status)?`<button class="btn-danger-fs" data-action="cancel-food" data-id="${f.food_id}">Cancel</button>`:''}</div></article>`).join(''):empty('Your first act of kindness is waiting.','Share surplus food and start making a difference.',addButton);}
async function requests(){const rows=await api('/my/requests');return {html:`${heading('Every request is a connection.','Accept requests, coordinate pickup, and complete the handover.')}<div class="tabs"><button class="chip selected" data-action="request-filter" data-value="all">All requests</button><button class="chip" data-action="request-filter" data-value="received">Received</button><button class="chip" data-action="request-filter" data-value="sent">Sent by me</button></div><div id="request-list">${requestList(rows)}</div>`,after:()=>{state.requests=rows;}};}
function requestList(rows){return rows.length?rows.map(r=>{const own=r.donor_id===state.user.user_id,valid=r.expires_at>Date.now()&&['Available','Reserved'].includes(r.food_status);return `<article class="request-card"><img src="${image(r)}" alt="${e(r.food_name)}"><div class="request-info"><h3><a href="#/food/${r.food_id}">${e(r.food_name)}</a></h3><p>${own?'Requested by '+e(r.receiver_name):'Donor: '+e(r.donor_name)} · ${e(r.pickup_area)}</p><p>${when(r.requested_at)} · ${badge(r.request_status)}</p></div><div class="request-actions">${own&&r.request_status==='Pending'&&valid?`<button class="btn-primary-fs" data-action="request-act" data-id="${r.request_id}" data-op="accept">Accept</button><button class="btn-danger-fs" data-action="request-act" data-id="${r.request_id}" data-op="reject">Decline</button>`:''}${['Accepted','Completed'].includes(r.request_status)?`<a class="btn-outline-fs" href="#/chat/${r.request_id}">${icon('chat')} Chat</a>`:''}${own&&r.request_status==='Accepted'&&valid?`<button class="btn-outline-fs" data-action="request-act" data-id="${r.request_id}" data-op="ready">Ready for pickup</button><button class="btn-primary-fs" data-action="request-act" data-id="${r.request_id}" data-op="collect">Confirm handover</button>`:''}${!own&&['Pending','Accepted'].includes(r.request_status)&&valid?`<button class="btn-danger-fs" data-action="request-act" data-id="${r.request_id}" data-op="cancel">Cancel request</button>`:''}</div></article>`;}).join(''):empty('No requests yet.','Find something nearby, or share a donation with your community.','<a class="btn-primary-fs" href="#/available">Explore food</a>');}
async function notifications(){const rows=await api('/notifications');state.notifications=rows;return {html:`${heading('A little news from your community.','Your requests, pickups and nearby donations.','<button class="btn-outline-fs" data-action="read-notifications">Mark all as read</button>')}<section class="panel">${rows.length?rows.map(n=>`<article class="notification-item ${n.is_read?'':'unread'}"><div class="stat-icon">${icon(n.notification_type==='message'?'chat':'bell')}</div><div><p>${e(n.message)}</p><small>${when(n.created_at)}</small></div></article>`).join(''):empty('You’re all caught up.','Notifications will appear here when your community connects.')}</section>`};}
async function profile(){const u=state.user;return {html:`${heading('Your place in the community.','Manage your profile and discovery location.')}<form class="panel" id="profile-form" style="max-width:850px"><div style="display:flex;gap:15px;align-items:center;margin-bottom:27px"><span class="avatar" style="width:65px;height:65px;font-size:23px">${e(initials(u.full_name))}</span><div><h2 style="font-size:20px;margin:0 0 5px">${e(u.full_name)}</h2><small style="color:#85917b">Member ID: ${e(u.user_id)}</small></div></div><div class="form-grid">${field('Full name','full_name','text',`required minlength="2" maxlength="100" value="${e(u.full_name)}"`)}${field('Email (optional)','email','email',`maxlength="254" value="${e(u.email||'')}"`)}<div class="form-field full"><label>Verified phone number</label><p>${e(u.phone_number)} <span class="status">Verified</span></p><small>Your number is private and cannot be changed through the profile form.</small></div><div class="form-field full"><div style="display:flex;justify-content:space-between"><label>Discovery location</label><button type="button" class="btn-outline-fs" data-action="form-gps">${icon('pin')} Use GPS</button></div><small>Tap the map or enter coordinates manually. GPS is optional.</small><div id="location-map" class="location-map"></div></div>${field('Latitude','latitude','number',`step="any" min="-90" max="90" value="${e(u.latitude??'')}"`)}${field('Longitude','longitude','number',`step="any" min="-180" max="180" value="${e(u.longitude??'')}"`)}</div><div class="form-actions"><button type="button" class="btn-outline-fs" data-action="clear-location">Clear location</button><button class="btn-primary-fs" type="submit">Save profile</button></div></form>`,after:()=>drawMap('location-map',[],true,loc=>{document.querySelector('[name=latitude]').value=loc.lat.toFixed(6);document.querySelector('[name=longitude]').value=loc.lng.toFixed(6);})};}
async function chat(requestId){const {request,messages}=await api(`/requests/${requestId}/messages`);state.currentChat=requestId;const writable=request.request_status==='Accepted'&&request.expires_at>Date.now();return {html:`${heading('A conversation over good food.',e(request.food_name),'<a class="btn-outline-fs" href="#/requests">Back to requests</a>')}<section class="panel chat-layout"><div class="section-heading"><h2>${icon('chat')} Pickup conversation</h2>${badge(request.request_status)}</div><div class="messages" id="messages">${messages.length?messages.map(messageHtml).join(''):'<p class="auth-note">Say hello and arrange your pickup. Your phone number stays private.</p>'}</div>${writable?`<form id="chat-form" class="chat-form" data-id="${requestId}"><input name="message_text" aria-label="Message" placeholder="Write a message…" required maxlength="2000" autocomplete="off"><button class="btn-primary-fs" type="submit">Send ${icon('arrow')}</button></form>`:'<p class="auth-note">This conversation is read-only after pickup or expiry.</p>'}<a class="btn-link-fs" style="display:inline-block;margin-top:15px" href="#/food/${request.food_id}">${icon('pin')} View pickup details</a></section>`,after:()=>{const box=document.querySelector('#messages');box.scrollTop=box.scrollHeight;}};}
function messageHtml(m){return `<div class="message ${m.sender_id===state.user.user_id?'mine':''}"><small>${e(m.sender_name||state.user.full_name)}</small><p>${e(m.message_text)}</p><small>${when(m.sent_at)}</small></div>`;}
function adminTabs(path){return `<div class="tabs">${[['/admin','Overview'],['/admin/users','Users'],['/admin/food','Food listings'],['/admin/requests','Requests'],['/admin/reports','Reports'],['/admin/analytics','Analytics'],['/admin/audit','Audit log']].map(([p,n])=>`<a href="#${p}" class="${p===path?'active':''}">${n}</a>`).join('')}</div>`;}
function table(headers,rows){return `<div class="panel table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" style="text-align:center">No records to show.</td></tr>`}</tbody></table></div>`;}
function barChart(title,rows){const items=rows.slice(-10),max=Math.max(...items.map(x=>x.value),1);return `<section class="panel"><h2 style="font-size:16px">${title}</h2>${items.length?`<div class="chart">${items.map(r=>`<div class="chart-col"><b>${r.value}</b><div class="chart-bar" style="height:${Math.max(5,r.value/max*115)}px"></div><small>${e(r.label)}</small></div>`).join('')}</div>`:'<p class="auth-note">Data will appear as your community grows.</p>'}</section>`;}
async function adminPage(path){
  if(!state.admin)return {html:empty('Admin verification required','Sign in with your verified phone and authenticator code.','<a class="btn-primary-fs" href="#/admin-login">Admin sign in</a>')};
  let content='',after;
  if(path==='/admin'||path==='/admin/analytics'){
    const s=await api('/admin/overview');content=stats([[s.users,'Registered users','Community members','people'],[s.donations,'Food donations','All-time listings','box'],[s.active,'Active listings','Available now','leaf'],[s.completed,'Completed pickups',`${s.meals} servings shared`,'check']])+`<div class="bottom-grid">${barChart('Daily donations',s.daily)}${barChart('Monthly donations',s.monthly)}${barChart('User growth',s.growth)}${barChart('Most active areas',s.areas)}</div><div class="tip">${icon('chart')}<p>${s.requests} total requests · ${s.expired} expired listings · ${s.completed} successful handovers</p></div>`;
  }else if(path==='/admin/users'){
    const rows=await api('/admin/users');content='<form id="user-search" class="filters"><input name="q" placeholder="Search by name or phone" aria-label="Search users"><button class="btn-primary-fs">Search users</button></form><div id="admin-user-list">'+userTable(rows)+'</div>';
  }else if(path==='/admin/food'){
    const rows=await api('/admin/food');state.adminFoods=rows;content=adminFilter('Food')+`<div id="admin-data-list">${adminFoodTable(rows)}</div>`;
  }else if(path==='/admin/requests'){
    const rows=await api('/admin/requests');state.adminRequests=rows;content=adminFilter('Requests')+`<div id="admin-data-list">${adminRequestTable(rows)}</div>`;
  }else if(path==='/admin/reports'){
    const rows=await api('/admin/reports');content=table(['Reported by','Concern','Target','Status','Action'],rows.map(r=>`<tr><td>${e(r.reporter_name)}</td><td style="white-space:normal;max-width:400px">${e(r.reason)}</td><td>${r.food_id?`<a href="#/food/${r.food_id}">Food listing</a>`:e(r.reported_user_id)}</td><td>${badge(r.status)}</td><td>${r.status==='Open'?`<button class="btn-outline-fs" data-action="resolve-report" data-id="${r.report_id}">Resolve</button>`:'Reviewed'}</td></tr>`));
  }else{
    const rows=await api('/admin/audit');content=table(['Administrator','Action','Target','Time'],rows.map(r=>`<tr><td>${e(r.admin_name)}</td><td>${e(r.action)}</td><td>${e(r.target_type)} · ${e(r.target_id)}</td><td>${when(r.created_at)}</td></tr>`));
  }
  return {html:heading('A community worth caring for.','Manage the platform, review activity, and keep sharing safe.','<button class="btn-outline-fs" data-action="export">'+icon('download')+' Export CSV</button>')+adminTabs(path)+content,after};
}
function adminFilter(kind){return `<form id="admin-filter" class="filters" data-kind="${kind}"><input name="q" placeholder="Search ${kind.toLowerCase()}" aria-label="Search ${kind}"><select name="status" aria-label="Status"><option value="">All statuses</option>${(kind==='Food'?['Available','Reserved','Collected','Expired','Cancelled']:['Pending','Accepted','Rejected','Completed','Cancelled','Expired']).map(s=>`<option>${s}</option>`).join('')}</select><button class="btn-primary-fs">Filter</button></form>`;}
function adminFoodTable(rows){return table(['Food','Donor','Area','Safe until','Status','Action'],rows.map(f=>`<tr><td>${e(f.food_name)}</td><td>${e(f.donor_name)}</td><td>${e(f.pickup_area)}</td><td>${when(f.expires_at)}</td><td>${badge(f.status)}</td><td>${['Available','Reserved'].includes(f.status)?`<button class="btn-danger-fs" data-action="cancel-food" data-id="${f.food_id}">Remove</button>`:'Closed'}</td></tr>`));}
function adminRequestTable(rows){return table(['Food','Requester','Status','Requested','Accepted','Completed'],rows.map(r=>`<tr><td>${e(r.food_name)}</td><td>${e(r.receiver_name)}</td><td>${badge(r.request_status)}</td><td>${when(r.requested_at)}</td><td>${r.accepted_at?when(r.accepted_at):'—'}</td><td>${r.collected_at?when(r.collected_at):'—'}</td></tr>`));}
function userTable(rows){return table(['Name','Phone (private)','Role','Status','Joined','Action'],rows.map(u=>`<tr><td>${e(u.full_name)}</td><td>${e(u.phone_number)}</td><td>${e(u.role)}</td><td>${badge(u.account_status)}</td><td>${when(u.created_at)}</td><td>${u.role==='admin'?'Protected':`<button class="${u.account_status==='active'?'btn-danger-fs':'btn-outline-fs'}" data-action="user-status" data-id="${u.user_id}" data-status="${u.account_status==='active'?'suspended':'active'}">${u.account_status==='active'?'Suspend':'Reactivate'}</button>`}</td></tr>`));}
function openModal(html){document.querySelector('#modal-content').innerHTML=html;modal.showModal();}
function confirmAction(title,description,run){openModal(`<h2>${e(title)}</h2><p style="color:#79846f;line-height:1.7">${e(description)}</p><div class="form-actions"><button class="btn-outline-fs" id="dialog-cancel">Keep it</button><button class="btn-primary-fs" id="dialog-confirm">Confirm</button></div>`);document.querySelector('#dialog-cancel').onclick=()=>modal.close();document.querySelector('#dialog-confirm').onclick=async()=>{modal.close();try{await run();}catch(err){toast(err.message,true);}};}
async function gps(){if(!navigator.geolocation)throw new Error('GPS is unavailable. Choose your location on the map.');return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude}),()=>reject(new Error('Location was unavailable. Tap the map or enter coordinates manually.')),{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));}
async function refreshUser(){const me=await api('/auth/me');state.user=me.user;state.csrf=me.csrf;state.admin=me.admin_verified;}
function connectSocket(){state.socket?.disconnect();state.socket=io(API_BASE||undefined,{withCredentials:true,auth:{csrf:state.csrf}});state.socket.on('notification',n=>{state.notifications.unshift(n);toast(n.message);document.querySelector('.bell')?.classList.add('has-unread');});state.socket.on('chat:message',m=>{if(location.hash===`#/chat/${m.request_id}`){const box=document.querySelector('#messages');if(box){if(!box.querySelector('.message'))box.innerHTML='';box.insertAdjacentHTML('beforeend',messageHtml(m));box.scrollTop=box.scrollHeight;}}});state.socket.on('listings:changed',async()=>{try{if(location.hash==='#/available'){const form=document.querySelector('#filter-form');if(form)await filterFoods(form);}else if(['#/requests','#/donations','#/map'].includes(location.hash))render();}catch{}});}
async function filterFoods(form){const params=new URLSearchParams([...new FormData(form)].filter(([,v])=>v));const foods=await api(`/food?${params}`);state.foods=foods;document.querySelector('#food-results').innerHTML=foodGrid(foods);document.querySelector('#food-count').textContent=foods.length;}
document.addEventListener('submit',async evt=>{
  const form=evt.target;if(!form.id)return;evt.preventDefault();const submit=form.querySelector('[type=submit]')||form.querySelector('button');if(submit)submit.disabled=true;
  try{
    const data=Object.fromEntries(new FormData(form));
    if(form.id==='login-form'){
      state.phone=data.phone_number.replace(/[\s()-]/g,'');if(!/^\+[1-9]\d{7,14}$/.test(state.phone))throw new Error('Enter an international phone number including + and country code.');
      state.authProfile={full_name:data.full_name,email:data.email,...(data.latitude?{latitude:Number(data.latitude),longitude:Number(data.longitude)}:{})};state.otp=await sendOTP(state.phone);go('/verify');
    }else if(form.id==='verify-form'){
      let payload={...state.authProfile,admin:state.adminLogin,totp:data.totp};
      if(state.config.demo)payload={...payload,challenge:state.otp.challenge,code:data.code};
      else{if(Date.now()-state.otp.createdAt>300000)throw new Error('Verification expired. Request another code.');const credential=await state.otp.confirmation.confirm(data.code);payload.id_token=await credential.user.getIdToken();}
      const result=await api('/auth/login',{method:'POST',body:payload});state.user=result.user;state.csrf=result.csrf;state.admin=result.admin_verified;state.otp=null;state.notifications=await api('/notifications');connectSocket();go(state.admin?'/admin':'/dashboard');toast('Welcome to your FoodSaver community.');
    }else if(form.id==='donation-form'){
      const body=new FormData(form);body.set('safe_storage',String(form.safe_storage.checked));body.set('prepared_at',new Date(data.prepared_at).toISOString());body.set('expires_at',new Date(data.expires_at).toISOString());body.set('has_image',String(Boolean(form.image.files.length)));if(!form.image.files.length)body.delete('image');
      const food=await api('/food',{method:'POST',body});toast('Your donation is live. Thank you for sharing!');go(`/food/${food.food_id}`);
    }else if(form.id==='filter-form'){await filterFoods(form);}
    else if(form.id==='profile-form'){
      const lat=data.latitude===''?null:Number(data.latitude),lng=data.longitude===''?null:Number(data.longitude);if((lat===null)!==(lng===null))throw new Error('Enter both latitude and longitude, or clear both.');
      await api('/profile',{method:'PATCH',body:{...data,latitude:lat,longitude:lng}});await refreshUser();toast('Your profile is updated.');render();
    }else if(form.id==='chat-form'){await api(`/requests/${form.dataset.id}/messages`,{method:'POST',body:data});form.reset();}
    else if(form.id==='user-search'){document.querySelector('#admin-user-list').innerHTML=userTable(await api(`/admin/users?q=${encodeURIComponent(data.q)}`));}
    else if(form.id==='admin-filter'){const food=form.dataset.kind==='Food',rows=(food?state.adminFoods:state.adminRequests).filter(r=>(!data.q||r.food_name.toLowerCase().includes(data.q.toLowerCase()))&&(!data.status||(food?r.status:r.request_status)===data.status));document.querySelector('#admin-data-list').innerHTML=food?adminFoodTable(rows):adminRequestTable(rows);}
    else if(form.id==='report-form'){await api('/reports',{method:'POST',body:{food_id:form.dataset.id,reason:data.reason}});modal.close();toast('Your concern has been sent to the admin team.');}
  }catch(error){toast(error.message,true);const box=form.querySelector('#auth-error');if(box){box.textContent=error.message;box.className='error-inline';}}
  finally{if(submit)submit.disabled=false;}
});
document.addEventListener('click',async evt=>{
  const button=evt.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  try{
    if(action==='menu'){document.querySelector('.sidebar').classList.toggle('open');}
    else if(action==='reload')render();
    else if(action==='logout'){await api('/auth/logout',{method:'POST'});state.socket?.disconnect();state.user=null;state.csrf=null;state.admin=false;state.notifications=[];go('/');}
    else if(action==='demo-account')document.querySelector('[name=phone_number]').value=button.dataset.phone;
    else if(action==='resend'){if(!state.config.demo){go(state.adminLogin?'/admin-login':'/login');toast('Enter your number again to resend with reCAPTCHA.');}else{state.otp=await sendOTP(state.phone);authPage('/verify');toast('A new demo code is ready.');}}
    else if(action==='request'){button.disabled=true;await api(`/food/${button.dataset.id}/request`,{method:'POST'});toast('Request sent. The donor will be notified.');go('/requests');}
    else if(action==='request-act'){
      const run=async()=>{await api(`/requests/${button.dataset.id}/${button.dataset.op}`,{method:'POST'});toast('Request updated.');render();};
      if(button.dataset.op==='collect')confirmAction('Confirm food handover','Confirm only after the requester has collected the food.',run);else await run();
    }else if(action==='cancel-food'){confirmAction('Close this donation','Active requests will be cancelled and requesters will be notified.',async()=>{await api(`/food/${button.dataset.id}/cancel`,{method:'POST'});toast('Donation closed.');render();});}
    else if(action==='report')openModal(`<h2>Report a concern</h2><p class="auth-note">Tell the admin team about food safety, a listing, or a pickup dispute.</p><form id="report-form" data-id="${button.dataset.id}"><div class="form-field"><label for="reason">What happened?</label><textarea id="reason" name="reason" required minlength="10" maxlength="2000"></textarea></div><div class="form-actions"><button class="btn-primary-fs" type="submit">Send report</button></div></form>`);
    else if(action==='read-notifications'){await api('/notifications/read',{method:'POST'});toast('Notifications marked as read.');render();}
    else if(action==='donation-filter'){document.querySelectorAll('[data-action=donation-filter]').forEach(b=>b.classList.toggle('selected',b===button));document.querySelector('#donation-list').innerHTML=donationList(state.donations.filter(f=>button.dataset.value==='All'||f.status===button.dataset.value));}
    else if(action==='request-filter'){document.querySelectorAll('[data-action=request-filter]').forEach(b=>b.classList.toggle('selected',b===button));document.querySelector('#request-list').innerHTML=requestList(state.requests.filter(r=>button.dataset.value==='all'||(button.dataset.value==='received'?r.donor_id===state.user.user_id:r.receiver_id===state.user.user_id)));}
    else if(action==='form-gps'){button.disabled=true;const pos=await gps();document.querySelector('[name=latitude]').value=pos.latitude.toFixed(6);document.querySelector('[name=longitude]').value=pos.longitude.toFixed(6);state.map.setView([pos.latitude,pos.longitude],15);state.selectMapLocation?.(L.latLng(pos.latitude,pos.longitude));toast('Location selected.');}
    else if(action==='registration-gps'){button.disabled=true;const pos=await gps();document.querySelector('[name=latitude]').value=pos.latitude;document.querySelector('[name=longitude]').value=pos.longitude;document.querySelector('#registration-location').textContent='Location selected. Used privately to find nearby food.';}
    else if(action==='gps'){button.disabled=true;const pos=await gps();await api('/profile',{method:'PATCH',body:{full_name:state.user.full_name,email:state.user.email,...pos}});await refreshUser();render();}
    else if(action==='clear-location'){document.querySelector('[name=latitude]').value='';document.querySelector('[name=longitude]').value='';}
    else if(action==='user-status'){confirmAction(button.dataset.status==='suspended'?'Suspend this account':'Reactivate this account',button.dataset.status==='suspended'?'This user will be signed out and their food listings will be hidden.':'This user will be able to sign in again.',async()=>{await api(`/admin/users/${button.dataset.id}`,{method:'PATCH',body:{account_status:button.dataset.status}});toast('Account updated.');render();});}
    else if(action==='resolve-report'){await api(`/admin/reports/${button.dataset.id}`,{method:'PATCH',body:{}});toast('Report resolved.');render();}
    else if(action==='export'){const type=location.hash==='#/admin/users'?'users':location.hash==='#/admin/requests'?'requests':'food';const res=await fetch(`/api/admin/export?type=${type}`);if(!res.ok)throw new Error('Export failed. Sign in as administrator again.');const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.download=`foodsaver-${type}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  }catch(error){toast(error.message,true);}finally{button.disabled=false;}
});
document.addEventListener('reset',evt=>{if(evt.target.id==='filter-form')setTimeout(()=>filterFoods(evt.target).catch(err=>toast(err.message,true)),0);});
document.addEventListener('change',evt=>{if(evt.target.id==='food-image'){const file=evt.target.files[0],preview=document.querySelector('#image-preview');if(state.previewUrl)URL.revokeObjectURL(state.previewUrl);if(file){state.previewUrl=URL.createObjectURL(file);preview.src=state.previewUrl;preview.hidden=false;}else preview.hidden=true;}});
document.querySelector('.modal-close').onclick=()=>modal.close();
window.addEventListener('hashchange',()=>{state.currentChat=null;render();});
try{state.config=await api('/config');try{await refreshUser();state.notifications=await api('/notifications');connectSocket();}catch{}await render();}catch(error){app.innerHTML=empty('FoodSaver is unavailable',e(error.message));}
